/// Saves `record` beside the history file of the prompt it came of.
pub fn save_record(prompt_file: &Path, record: &RunRecord) -> Result<()> {
    let file = record_path(prompt_file);
    let json = serde_json::to_string_pretty(record)?;
    fs::write(&file, json).with_context(|| format!("could not save {}", file.display()))
}

/// The project's prompt history, oldest first. Files that do not read back as
/// a hidden anchor are left out; a record that is missing or does not read
/// back is `None`.
pub fn load(project_dir: &Path) -> Vec<SavedPrompt> {
    load_dir(&hidden_anchor::history_dir(project_dir))
}

/// The questions asked in the project, oldest first, read back like the
/// prompt history.
pub fn load_asks(project_dir: &Path) -> Vec<SavedPrompt> {
    load_dir(&hidden_anchor::asks_dir(project_dir))
}

fn load_dir(dir: &Path) -> Vec<SavedPrompt> {
    let Ok(entries) = fs::read_dir(dir) else {
        return Vec::new();
    };
    let mut files: Vec<(u64, PathBuf)> = entries
        .filter_map(|entry| Some(entry.ok()?.path()))
        .filter(|path| path.extension().is_some_and(|ext| ext == "pi"))
        .map(|path| (sent_at(&path), path))
        .collect();
    files.sort();
    files
        .into_iter()
        .filter_map(|(_, file)| {
            let (anchor, text) = HiddenAnchor::parse(&fs::read_to_string(&file).ok()?)?;
            let record = fs::read_to_string(record_path(&file))
                .ok()
                .and_then(|json| serde_json::from_str(&json).ok());
            Some(SavedPrompt {
                anchor,
                text,
                record,
            })
        })
        .collect()
}

        bail!("{stderr}");
    }
    Ok(())
}

/// Translates one line of `stream-json` output. Events from subagents (those
/// with a `parent_tool_use_id`) are left out so the reply reads as one thread.
pub fn parse(event: &Value) -> Vec<HarnessEvent> {
    if event
        .get("parent_tool_use_id")
        .is_some_and(|parent| !parent.is_null())
    {
        return Vec::new();
    }

    match str_at(event, "/type").as_deref() {
        Some("system") if str_at(event, "/subtype").as_deref() == Some("init") => {
            str_at(event, "/session_id")
                .map(HarnessEvent::Session)
                .into_iter()
                .collect()
        }
        Some("stream_event") => {
            let inner = &event["event"];
            match str_at(inner, "/type").as_deref() {
                Some("content_block_start") => {
                    match str_at(inner, "/content_block/type").as_deref() {
                        Some("text") => vec![HarnessEvent::TextStarted],
                        Some("tool_use") => match (
                            str_at(inner, "/content_block/id"),
                            str_at(inner, "/content_block/name"),
                        ) {
                            (Some(id), Some(name)) => vec![HarnessEvent::ToolStarted { id, name }],
                            _ => Vec::new(),
                        },
                        _ => Vec::new(),
                    }
                }
                Some("content_block_delta")
                    if str_at(inner, "/delta/type").as_deref() == Some("text_delta") =>
                {
                    str_at(inner, "/delta/text")
                        .map(HarnessEvent::TextDelta)
                        .into_iter()
                        .collect()
                }
                _ => Vec::new(),
            }
        }
        Some("assistant") => content_blocks(event, "tool_use")
            .filter_map(|block| {
                Some(HarnessEvent::ToolInput {
                    id: str_at(block, "/id")?,
                    summary: summarize(block.get("input")?)?,
                })
            })
            .collect(),
        Some("user") => content_blocks(event, "tool_result")
            .filter_map(|block| {
                Some(HarnessEvent::ToolFinished {
                    id: str_at(block, "/tool_use_id")?,
                    is_error: block
                        .get("is_error")
                        .and_then(Value::as_bool)
                        .unwrap_or(false),
                })
            })
            .collect(),
        Some("result") => vec![HarnessEvent::Finished {
            is_error: event
                .get("is_error")
                .and_then(Value::as_bool)
                .unwrap_or(false),
            result: str_at(event, "/result").unwrap_or_default(),
        }],
        _ => Vec::new(),
    }
}

fn str_at(value: &Value, pointer: &str) -> Option<String> {
    value.pointer(pointer)?.as_str().map(str::to_string)
}

fn content_blocks<'a>(event: &'a Value, kind: &'a str) -> impl Iterator<Item = &'a Value> {
    event
        .pointer("/message/content")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(move |block| block.get("type").and_then(Value::as_str) == Some(kind))
}

